/* @lc app=leetcode id=2208 lang=kotlin */ class Solution { fun halveArray(nums: IntArray): Int = java.util.PriorityQueue<Double>(compareByDescending { it }).apply { nums.forEach { add(it.toDouble()) } }.let { pq -> nums.sumOf { it.toDouble() }.let { sum -> generateSequence(sum to 0) { (s, c) -> if (s > sum / 2.0 + 1e-9) pq.poll()!!.let { half -> (s - half / 2.0).also { pq.add(half / 2.0) } to (c + 1) } else null }.last().second } } }